{
  "name": "guide",
  "private": true,
  "author": "",
  "type": "module",
  "scripts": {
    "start": "vp build --watch --mode development --minify false --sourcemap inline",
    "build": "vp build",
    "format": "vp fmt",
    "fix": "vp check --fix",
    "lint:css": "stylelint \"**/*.scss\"",
    "lint:js": "vp lint --report-unused-disable-directives",
    "lint:format": "vp fmt --check",
    "lint": "npm run lint:js && npm run lint:css && npm run lint:format",
    "test": "vp test run"
  },
  "dependencies": {
    "@popperjs/core": "^2.11.5",
    "bootstrap": "^5.3.8"
  },
  "devDependencies": {
    "@wagtail/stylelint-config-wagtail": "^2.0.1",
    "browserslist": "^4.29.3",
    "happy-dom": "^20.14.5",
    "sass": "^1.49.8",
    "stylelint": "^17.16.0",
    "vite-plus": "^1.0.0"
  },
  "overrides": {
    "vite": "npm:@voidzero-dev/vite-plus-core@latest",
    "vitest": "5.0.1"
  },
  "browserslist": [
    "Firefox ESR",
    "last 2 Chrome versions",
    "last 2 ChromeAndroid versions",
    "last 2 Edge versions",
    "last 1 Firefox version",
    "last 2 iOS versions",
    "last 3 Safari versions",
    "not safari 13",
    "not ie 11"
  ],
  "devEngines": {
    "packageManager": {
      "name": "npm"
    }
  }
}

import { readdirSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import browserslist from 'browserslist';
import { defineConfig, type Plugin } from 'vite-plus';

const source = resolve(import.meta.dirname, 'apps/frontend/static_src');
const destination = resolve(import.meta.dirname, 'apps/frontend/static');

// Vite wants esbuild-style targets (e.g. `chrome153`), so convert the lowest
// browser versions of the `browserslist` in package.json. Otherwise Vite
// down-levels CSS such as `light-dark()` for its own, older default targets.
const targetNames: Record<string, string> = {
  and_chr: 'chrome',
  chrome: 'chrome',
  edge: 'edge',
  firefox: 'firefox',
  ios_saf: 'ios',
  safari: 'safari',
};
const lowestVersions: Record<string, number> = {};
browserslist().forEach((entry) => {
  const [id, version] = entry.split(' ');
  const name = targetNames[id];
  if (name) {
    lowestVersions[name] = Math.min(
      lowestVersions[name] ?? Infinity,
      parseFloat(version),
    );
  }
});
const target = Object.entries(lowestVersions).map(
  ([name, version]) => `${name}${version}`,
);

/**
 * Copies the static images to the build output, and writes a flat
 * `manifest.json` (entry name -> built file name) for django-manifest-loader.
 * Vite's own manifest is keyed by source path, which the loader can't read.
 */
const djangoManifest = (): Plugin => ({
  name: 'django-manifest',
  enforce: 'post',
  generateBundle(_options, bundle) {
    const manifest: Record<string, string> = {};
    const imagesDir = join(source, 'images');
    readdirSync(imagesDir).forEach((name) => {
      const fileName = `images/${name}`;
      this.emitFile({
        type: 'asset',
        fileName,
        source: readFileSync(join(imagesDir, name)),
      });
      manifest[fileName] = fileName;
    });

    Object.values(bundle).forEach((item) => {
      if (item.type === 'chunk') {
        if (item.isEntry) manifest[`${item.name}.js`] = item.fileName;
      } else {
        manifest[item.names[0] ?? item.fileName] = item.fileName;
      }
    });

    this.emitFile({
      type: 'asset',
      fileName: 'manifest.json',
      source: JSON.stringify(manifest, null, 2),
    });
  },
});

export default defineConfig({
  // Relative URLs, so the built CSS works wherever Django serves /static/ from.
  base: './',
  publicDir: false,
  plugins: [djangoManifest()],
  css: {
    preprocessorOptions: {
      scss: {
        // Bootstrap 5 and our own stylesheets still use `@import`.
        quietDeps: true,
        silenceDeprecations: ['import'],
      },
    },
  },
  build: {
    target,
    outDir: destination,
    emptyOutDir: true,
    assetsDir: '',
    modulePreload: false,
    rolldownOptions: {
      input: {
        blocking: join(source, 'js', 'blocking.js'),
        main: join(source, 'js', 'main.js'),
      },
      output: {
        entryFileNames: '[name]-[hash].js',
        chunkFileNames: '[name]-[hash].js',
        assetFileNames: '[name]-[hash][extname]',
      },
    },
  },
  lint: {
    env: { browser: true },
    categories: {
      correctness: 'error',
      suspicious: 'error',
      perf: 'error',
    },
    ignorePatterns: ['apps/frontend/static/**', 'cloudflare/**'],
  },
  fmt: {
    printWidth: 80,
    singleQuote: true,
    trailingComma: 'all',
    quoteProps: 'consistent',
    ignorePatterns: ['apps/frontend/static/**', '**/vendor/**', '*.html'],
  },
  test: {
    environment: 'happy-dom',
    include: ['apps/frontend/static_src/**/*.test.js'],
  },
});

{% load core_tags wagtailcore_tags wagtailroutablepage_tags wagtailuserbar wagtail_cache manifest i18n %}

{% wagtail_site as current_site %}
{% get_current_language_bidi as LANGUAGE_BIDI %}
{% get_current_language as LANGUAGE_CODE %}
<!DOCTYPE html>
<html lang="{% block lang %}{{ self.locale.language_code }}{% endblock %}" dir="{% if LANGUAGE_BIDI %}rtl{% else %}ltr{% endif %}" class="no-js">
    <head>
        <meta charset="utf-8" />
        <title>
            {% block title %}
                {% if page.seo_title %}{{ page.seo_title }}{% else %}{{ page.title }}{% endif %}
            {% endblock %}
            {% block title_suffix %}
                {% if current_site and current_site.site_name %}- {{ current_site.site_name }}{% endif %}
            {% endblock %}
        </title>
        {# always render the tag even if empty - picked up by our built-in check #}
        <meta name="description" content="{{ page.search_description }}" />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <meta name="color-scheme" content="light dark">

        {# WebMCP origin trial until Chrome 162 #}
        <meta http-equiv="origin-trial" content="AmXV/Pu7QOW0gCV9tEZDFAQ9hcSd+Hw42EpnR6d23qfJE8SuVEI1H3GYjhPU16+GGfwgycjFJ3rFLbjKD9lK7gcAAABReyJvcmlnaW4iOiJodHRwczovL2d1aWRlLndhZ3RhaWwub3JnOjQ0MyIsImZlYXR1cmUiOiJXZWJNQ1AiLCJleHBpcnkiOjE4MDYzNjQ4MDB9">

        {% comment %}
        Prevent specific views indexing, with the robots=noindex meta tag.
        {% endcomment %}
        {% if SEO_NOINDEX %}
        <meta name="robots" content="noindex">
        {% endif %}

        {# Open links in a new tab if the page is rendered in the preview panel #}
        {% if request.in_preview_panel %}
            <base target="_blank">
        {% endif %}

        <link rel="apple-touch-icon" sizes="180x180" href="{% manifest 'images/apple-touch-icon.png' %}">
        <link rel="icon" type="image/png" sizes="32x32" href="{% manifest 'images/favicon-32x32.png' %}">
        <link rel="icon" type="image/png" sizes="16x16" href="{% manifest 'images/favicon-16x16.png' %}">

        {# alternate tags #}
        {% hreflangs %}

        {% if page %}
            <link rel="canonical" href="{{ page.full_url }}">
        {% endif %}

        <link rel="ai-catalog" href="/.well-known/ai-catalog.json">
        <link rel="api-catalog" href="/.well-known/api-catalog">
        <link rel="service-desc" type="application/vnd.oai.openapi+json;version=3.1" href="{% url 'wagtailapi_v3:openapi-json' %}">

        {% if page.has_markdown_route %}
            <link rel="alternate" type="text/markdown;charset=utf-8" href="{{ page.get_site.root_url }}{% routablepageurl page 'markdown' %}" />
        {% endif %}

        {% comment %}
            Twitter summary card - see https://dev.twitter.com/cards/types/summary
            and https://dev.twitter.com/cards/getting-started
        {% endcomment %}
        <meta name="twitter:card" content="summary" />
        <meta name="twitter:site" content="@wagtailcms" />
        <meta name="twitter:title" content="{{ page.title }}" />
        <meta name="twitter:description" content="{% if page.search_description %}{{ page.search_description }}{% endif %}">
        <meta name="twitter:image" content="{{ current_site.root_url }}{% manifest 'images/social-image.png' %}">

        {# facebook opengraph tags #}
        <meta property="og:type" content="website" />
        <meta property="og:url" content="{{ site.root_url }}{{ page.url }}" />
        <meta property="og:title" content="{{ page.title }}" />
        <meta name="og:image" content="{{ current_site.root_url }}{% manifest 'images/social-image.png' %}">
        <meta property="og:description" content="{% if page.search_description %}{{ page.search_description }}{% endif %}" />
        <meta property="og:site_name" content="{{ current_site.site_name }}" />

        {# Global stylesheets #}
        <link rel="stylesheet" href="{% manifest 'main.css' %}">

        {% block extra_css %}
        {# Override this in templates to add extra stylesheets #}
        {% endblock %}

        <script type="application/ld+json">
        {
          "@context": "https://schema.org",
          "@type": "WebPage",
          "headline": "{{ page.title|escapejs }}",
          "datePublished": "{{ page.first_published_at|date:'c' }}",
          "dateModified": "{{ page.last_published_at|date:'c' }}"
        }
        </script>
    </head>

    <body class="app">

        {# blocking js loaded first to ensure no flash of white on theme detection #}
        <script src="{% manifest 'blocking.js' %}"></script>

        {% include "components/skip_link.html" %}
        {% wagtailuserbar %}

        <div class="grid">
            <div class="app__header">
                {# The header only varies by language - the active menu item is highlighted client-side. #}
                {% wagtailcache 86400 header LANGUAGE_CODE %}
                    {% header %}
                {% endwagtailcache %}
            </div>

            <div class="app__content">
                <div class="page-tools">
                    {% include "components/theme_toggle.html" %}
                    {% if page.has_markdown_route %}
                        {% include "components/copy_button.html" %}
                    {% endif %}
                    {# The selector only changes when the page's translations do. #}
                    {% wagtailcache 86400 language_selector LANGUAGE_CODE page.id %}
                        {% language_selector %}
                    {% endwagtailcache %}
                </div>
                <main id="main-content">
                    {% block content %}{% endblock %}
                </main>
            </div>
        </div>

        <footer class="app__footer">
            {% footer %}
        </footer>

        {% include "components/search_modal.html" %}

        {# Global javascript #}
        <script nonce="{{ csp_nonce }}">var languageCode = '{{ self.locale.language_code }}';</script>
        <script src="{% url 'javascript-catalog' %}"></script>
        <script src="{% manifest 'main.js' %}"></script>

        {% block extra_js %}
        {# Override this in templates to add extra javascript #}
        {% endblock %}
    </body>
</html>

/* global ngettext, interpolate */
import { debounce } from './debounce';
import '../scss/main.scss';
import './theme-detect';
import { initSectionLink } from './section-link';
import { initActiveNavItem } from './active-nav-item';
import { handleFeedback } from './feedback';
import { initWebMcp } from './webmcp';
import MobileMenu from './mobile-menu';
import CopyButton from './copy-button';

initSectionLink();
initActiveNavItem();
handleFeedback();
initWebMcp();

const searchInput = document.querySelector('[data-search-input]');
const searchModal = document.getElementById('search-modal');
const resultsDiv = document.querySelector('[data-results]');
const resultsCountContainer = document.querySelector(
  '[data-results-count-container]',
);

const removeExistingChildren = (parent) => {
  parent.innerHTML = '';
};

const injectResultsInHTML = (results) => {
  removeExistingChildren(resultsDiv);
  removeExistingChildren(resultsCountContainer);

  const resultsCountHeading = document.createElement('h2');
  resultsCountHeading.dir = 'auto';
  const resultHeadingString = ngettext(
    '%s result found.',
    '%s results found.',
    results.length,
  );
  resultsCountHeading.innerText = interpolate(resultHeadingString, [
    results.length,
  ]);
  resultsCountHeading.classList.add('autocomplete__count');
  resultsCountContainer.appendChild(resultsCountHeading);

  results.forEach((result, index) => {
    const resultDiv = document.createElement('a');
    resultDiv.dir = 'auto';
    const resultHeading = document.createElement('h3');
    resultHeading.dir = 'auto';
    const resultDescription = document.createElement('div');
    resultDescription.dir = 'auto';
    const resultParentSection = document.createElement('div');
    resultParentSection.dir = 'auto';
    resultHeading.innerText = result.title;
    resultDescription.innerText = result.search_description;
    resultParentSection.innerText = result.parent_section;
    resultDiv.href = result.full_url;
    resultDiv.appendChild(resultParentSection);
    resultDiv.appendChild(resultHeading);
    resultDiv.appendChild(resultDescription);
    resultParentSection.classList.add('autocomplete__meta');
    resultDescription.classList.add('autocomplete__description');
    resultDiv.classList.add('autocomplete__row');
    resultHeading.classList.add('autocomplete__heading');
    resultsDiv.appendChild(resultDiv);

    requestAnimationFrame(() => {
      setTimeout(() => {
        resultDiv.classList.add('is-visible');
      }, index * 400);
    });
  });
};

const onSearchInputChange = async (event) => {
  const query = event.target.value.trim();

  if (!query) {
    removeExistingChildren(resultsDiv);
    removeExistingChildren(resultsCountContainer);
    return;
  }

  document.querySelector('.search__container').classList.add('is-loading');

  const minDelay = new Promise((resolve) => {
    setTimeout(resolve, 200);
  });

  try {
    const res = await fetch(
      `${window.location.origin}${
        window.languageCode ? `/${window.languageCode}` : ''
      }/search_json/?${new URLSearchParams({
        query,
      }).toString()}`,
    );
    const data = await res.json();
    injectResultsInHTML(data);
  } catch (err) {
    console.log(err);
    window.alert(`Error: ${err}`);
  } finally {
    await minDelay; // wait for 300ms to pass if fetch was faster
    document.querySelector('.search__container').classList.remove('is-loading');
  }
};
const onSearchInputKeyUp = debounce(onSearchInputChange, 150);

searchInput.addEventListener('keyup', (event) => {
  if (event.key === 'Tab') return;
  onSearchInputKeyUp(event);
});

searchModal.addEventListener('shown.bs.modal', () => {
  searchInput.focus();
});

searchModal.addEventListener('hidden.bs.modal', () => {
  searchInput.value = '';
  removeExistingChildren(resultsDiv);
  removeExistingChildren(resultsCountContainer);
});

function initComponent(ComponentClass) {
  const items = document.querySelectorAll(ComponentClass.selector());
  items.forEach((item) => new ComponentClass(item));
}

document.addEventListener('DOMContentLoaded', () => {
  // Remove no-js class if JS is enabled
  document.documentElement.classList.remove('no-js');
  initComponent(MobileMenu);
  initComponent(CopyButton);
});
